import{_ as e,c as i,o as t,ag as s}from"./chunks/framework.B-XtCDNB.js";const u=JSON.parse('{"title":"Bindings","description":"Bindings A Vala binding maps Vala syntax to the C code used in a library. It is often a single Vala API file (.vapi), but can also include a dependencies file (.deps). Sources Of Bindings Upstream...","frontmatter":{"prev":{"text":"Guides","link":"/guides/"},"next":{"text":"Generating a VAPI with GObject Introspection","link":"/guides/bindings/generating-a-vapi-with-gobject-introspection"}},"headers":[],"relativePath":"guides/bindings.md","filePath":"guides/bindings.md","lastUpdated":1785589401000}'),n={name:"guides/bindings.md"};function o(r,a,l,d,h,p){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="bindings" tabindex="-1">Bindings <a class="header-anchor" href="#bindings" aria-label="Permalink to &quot;Bindings&quot;">​</a></h1><p>A Vala binding maps Vala syntax to the C code used in a library. It is often a single Vala API file (<code>.vapi</code>), but can also include a dependencies file (<code>.deps</code>).</p><h2 id="sources-of-bindings" tabindex="-1">Sources Of Bindings <a class="header-anchor" href="#sources-of-bindings" aria-label="Permalink to &quot;Sources Of Bindings&quot;">​</a></h2><h3 id="upstream-projects" tabindex="-1">Upstream Projects <a class="header-anchor" href="#upstream-projects" aria-label="Permalink to &quot;Upstream Projects&quot;">​</a></h3><p>The first source of bindings is from upstream projects. If a project uses GLib with GObjects then a Vala binding can be generated automatically as part of the build process.</p><p>The resulting VAPI file can be distributed with the project and ensures it is the most compatible with the project.</p><p>For projects not using GObjects a manually written VAPI can be distributed. See <a href="./bindings/upstream-guide.html">Why Distribute Bindings Upstream</a> for details on using either process in an upstream project.</p><h3 id="distributed-with-vala" tabindex="-1">Distributed with Vala <a class="header-anchor" href="#distributed-with-vala" aria-label="Permalink to &quot;Distributed with Vala&quot;">​</a></h3><p>The Vala project also includes a large number of bindings for projects that do not distribute the VAPI files.</p><p>You can check them out in the <code>vapi</code> directory in the Vala compiler&#39;s repository: <a href="https://gitlab.gnome.org/GNOME/vala/-/tree/main/vapi" target="_blank" rel="noreferrer">https://gitlab.gnome.org/GNOME/vala/-/tree/main/vapi</a></p><h3 id="other-notable-sources" tabindex="-1">Other notable sources <a class="header-anchor" href="#other-notable-sources" aria-label="Permalink to &quot;Other notable sources&quot;">​</a></h3><ul><li><a href="https://github.com/nemequ/vala-girs" target="_blank" rel="noreferrer">vala-girs</a> — GIR packages and related bindings metadata</li><li><a href="https://gitlab.gnome.org/GNOME/vala-extra-vapis" target="_blank" rel="noreferrer">vala-extra-vapis</a> — Additional VAPI files maintained with by the GNOME Vala project that aren&#39;t distributed with Vala</li></ul><h3 id="writing-your-own-vapi-files" tabindex="-1">Writing your own VAPI files <a class="header-anchor" href="#writing-your-own-vapi-files" aria-label="Permalink to &quot;Writing your own VAPI files&quot;">​</a></h3><p>You can also write your own <code>.vapi</code> files or use a custom <code>.vapi</code> file that someone else has written.</p><p>Check out the <a href="#contents">contents</a> of the guide to learn how.</p><h2 id="how-to-use-vapi-files-that-aren-t-distributed-with-packages" tabindex="-1">How to use VAPI files that aren&#39;t distributed with packages <a class="header-anchor" href="#how-to-use-vapi-files-that-aren-t-distributed-with-packages" aria-label="Permalink to &quot;How to use VAPI files that aren&#39;t distributed with packages&quot;">​</a></h2><p>When <code>.vapi</code> aren&#39;t distributed with a package you want to use, you can download or write your own <code>.vapi</code> file and compile your program with it by using the <code>--vapidir</code> option in <code>valac</code>.</p><p>For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">valac</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vapidir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/vapi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkg_name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.vala</span></span></code></pre></div><p>Typically you would set <code>--vapidir</code> to local directory called <code>vapi</code> in your project. For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">valac</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vapidir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./vapi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkg_name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.vala</span></span></code></pre></div><h2 id="documentation-of-bindings" tabindex="-1">Documentation of Bindings <a class="header-anchor" href="#documentation-of-bindings" aria-label="Permalink to &quot;Documentation of Bindings&quot;">​</a></h2><p>Documentation of bindings may be included in <a href="https://valadoc.org" target="_blank" rel="noreferrer">https://valadoc.org</a></p><p>For more info on how to generate your own documentation, check out the <a href="./valadoc-guide.html">Valadoc Guide</a>.</p><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to &quot;Contents&quot;">​</a></h2><ul class="section-toc"><li><a href="bindings/generating-a-vapi-with-gobject-introspection">Generating a VAPI with GObject Introspection</a></li><li><a href="bindings/upstream-guide">Why Distribute Bindings Upstream</a></li><li><a href="bindings/writing-a-vapi-manually">Writing a VAPI Manually</a></li></ul>',26)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
